CREATE TABLE application_host_applications (
 app_id TEXT PRIMARY KEY NOT NULL CHECK(length(app_id) BETWEEN 1 AND 64 AND app_id GLOB '[a-z]*' AND app_id NOT GLOB '*[^a-z0-9-]*')
)

CREATE TRIGGER m14_profile_revision_delete AFTER DELETE ON ai_profiles BEGIN
 UPDATE m14_profile_execution_revision SET revision=revision+1,present=0 WHERE profile_id=OLD.id;
END

CREATE TRIGGER m14_provider_secret_revision_delete AFTER DELETE ON app_secrets BEGIN
 UPDATE m14_profile_execution_revision SET revision=revision+1 WHERE present=1 AND profile_id IN (SELECT c.profile_id FROM ai_run_configs c JOIN ai_providers p ON c.provider_id=p.id WHERE p.secret_ref=OLD.key);
END

CREATE TRIGGER m14_provider_secret_revision_insert AFTER INSERT ON app_secrets BEGIN
 UPDATE m14_profile_execution_revision SET revision=revision+1 WHERE present=1 AND profile_id IN (SELECT c.profile_id FROM ai_run_configs c JOIN ai_providers p ON c.provider_id=p.id WHERE p.secret_ref=NEW.key);
END

CREATE TRIGGER m14_provider_secret_revision_update AFTER UPDATE ON app_secrets WHEN OLD.key IS NOT NEW.key OR OLD.secret IS NOT NEW.secret BEGIN
 UPDATE m14_profile_execution_revision SET revision=revision+1 WHERE present=1 AND profile_id IN (SELECT c.profile_id FROM ai_run_configs c JOIN ai_providers p ON c.provider_id=p.id WHERE p.secret_ref=NEW.key OR p.secret_ref=OLD.key);
END
